public static String rectangle(int m, int n) {
    String s = "";
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            s = s + "*";
        }
        if (i < m) {
            s = s + "\n";   // בין שורה לשורה
        }
    }
    return s;
}

public static String triangle(int n) {
    String s = "";
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {   // בשורה i יש i כוכביות
            s = s + "*";
        }
        if (i < n) {
            s = s + "\n";
        }
    }
    return s;
}

public static String numberTriangle(int n) {
    String s = "";
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            s = s + j;
            if (j < i) {
                s = s + " ";
            }
        }
        if (i < n) {
            s = s + "\n";
        }
    }
    return s;
}

